public static Widget Basic(StoryContext ctx)
{
    PlayerGame game = PlayerLoader.LoadStart(FixtureProject());
    Player2DWorld world = game.World2D;
    float w = game.Project.WindowWidth, h = game.Project.WindowHeight;

